	//#region src/engine/warmup.ts
	const WARMUP = {
		progressive: {
			sets: 2,
			reps: 6
		},
		simple: {
			sets: 1,
			reps: 10
		}
	};
	function warmupStyleFor(level, returning = false) {
		return level === "iniciante" || returning ? "simple" : "progressive";
	}
	/** Progressive goes from 40% to 80% (one set alone at 80%); simple stays at 40%. */
	function warmupPercents(sets, style) {
		if (sets <= 0) return [];
		if (style === "simple") return Array.from({ length: sets }, () => .4);
		if (sets === 1) return [.8];
		return Array.from({ length: sets }, (_, i) => .4 + .4 * i / (sets - 1));
	}
	/** "2 séries de 6, com 40% e 80% da carga de trabalho" or "1 série de 10, com 40%...". */
	function warmupRule(sets, style) {
		const pcts = [...new Set(warmupPercents(sets, style).map((p) => `${Math.round(p * 100)}%`))];
		const list = pcts.length > 1 ? `${pcts.slice(0, -1).join(", ")} e ${pcts[pcts.length - 1]}` : pcts[0];
		const reps = WARMUP[style].reps;
		return `${sets} ${sets === 1 ? "série" : "séries"} de ${reps}, com ${list} da carga de trabalho`;
	}
