	//#region src/engine/substitute.ts
	function isAvailable(e, o) {
		if (o.without?.includes(e.equipment)) return false;
		if (o.available && e.equipment !== "peso_corporal" && !o.available.includes(e.equipment)) return false;
		if (o.spareJoints?.some((j) => e.joints.includes(j))) return false;
		if (o.excludeIds?.includes(e.id)) return false;
		return true;
	}
