	/**
	* Fichas of each split style, in rotation order. Muscle groups: A chest and triceps,
	* B back and biceps, C legs, the classic gym ficha; four adds shoulders and abs,
	* five splits arms off too.
	*/
	function fichasFor(style, fichas, gymDays, focus = "equilibrado") {
		if (focus === "pernas" && style === "superior_inferior") {
			if (gymDays >= 5) return [
				"anterior",
				"superiores",
				"posterior",
				"superiores_b",
				"gluteos"
			];
			if (gymDays >= 4) return [
				"anterior",
				"superiores",
				"posterior_gluteos",
				"superiores_b"
			];
			return [
				"anterior",
				"superiores",
				"posterior_gluteos"
			];
		}
		if (focus === "pernas" && style === "grupos") {
			if (fichas >= 5) return [
				"anterior",
				"superiores",
				"posterior",
				"superiores_b",
				"gluteos"
			];
			if (fichas === 4) return [
				"anterior",
				"superiores",
				"posterior",
				"gluteos"
			];
			return [
				"anterior",
				"superiores",
				"posterior_gluteos"
			];
		}
		switch (style) {
			case "corpo_inteiro": return ["corpo_inteiro_a", "corpo_inteiro_b"];
			case "superior_inferior": return gymDays >= 4 ? [
				"superior_a",
				"inferior_a",
				"superior_b",
				"inferior_b"
			] : ["superior_a", "inferior_a"];
			default:
				if (fichas >= 5) return [
					"peito",
					"costas",
					"perna",
					"ombro_abdomen",
					"bracos"
				];
				if (fichas === 4) return [
					"peito_triceps",
					"costas_biceps",
					"perna",
					"ombro_abdomen"
				];
				return [
					"peito_triceps",
					"costas_biceps",
					"perna"
				];
		}
	}
